  ('019fa2a1-6d4d-76ee-82a7-7ee857325920', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6d06-750a-9c65-845342800227', 'service', 'service', 'The service used, e.g. `twitter` or `github`.', NULL, true, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 2, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
