  ('019fa2a1-6d70-76b2-a087-fe70b28dfa9e', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6d06-750a-9c65-845342800227', 'details', 'details', 'Additional profile details extracted from this login method', NULL, true, false, NULL, NULL, NULL, NULL, NULL, '{"name":"jsonb"}', 4, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6d82-7a24-bdbe-4633404ec25a', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6d06-750a-9c65-845342800227', 'is_verified', 'is_verified', 'Whether this connected account has been verified', NULL, true, false, '{"value":false}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 5, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6e13-7815-8fd3-261e273bf2d5', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'id', 'id', NULL, NULL, true, false, '{"function":"uuidv7"}', NULL, NULL, NULL, NULL, '{"name":"uuid"}', 0, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6e2b-7af1-9ce3-0b69d171b046', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'slug', 'slug', 'Stable identifier (e.g. ''google'', ''github'', ''custom:acme-okta''). Used as connected_accounts.service value. Custom providers must use the custom:<slug> namespace; format ^[a-z0-9][a-z0-9_-]{0,30}[a-z0-9]$ enforced by admin procedure.', NULL, true, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 1, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6e3c-7f8f-808a-23da32526375', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'kind', 'kind', 'Protocol family: ''oauth2'' (manual endpoint configuration) or ''oidc'' (discovery + JWKS-verified id_token). Future kinds (''saml'') will use a different field set.', NULL, true, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 2, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6e4d-725d-a8b7-b21d828e48db', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'display_name', 'display_name', 'Human-readable label for client UIs (e.g. ''Sign in with Google'', ''Acme Okta''). Exposed via the public-safe view.', NULL, true, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 3, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6e5c-7d59-8767-51a01cea9c22', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'enabled', 'enabled', 'Whether sign-in via this provider is currently allowed. Toggled by enable_identity_provider / disable_identity_provider admin procedures. Disabled providers remain in the public-safe view as enabled=false so client UIs can grey out the button.', NULL, true, false, '{"value":true}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 4, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6e72-7fcb-a733-a26e78b79368', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'authorization_url', 'authorization_url', 'OAuth2 authorization endpoint (where the user is redirected to grant consent). Required when kind = ''oauth2''; for kind = ''oidc'' resolved from cached discovery_doc.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 5, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6e7d-79b5-96ae-f4ff44feb736', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'token_url', 'token_url', 'OAuth2 token endpoint (exchanges authorization code for access/id tokens). Required when kind = ''oauth2''; for kind = ''oidc'' resolved from cached discovery_doc.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 6, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6e88-78c3-9ea9-6bb797a2826b', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'userinfo_url', 'userinfo_url', 'OAuth2 userinfo endpoint (returns the user profile given an access token). Required when kind = ''oauth2''; for kind = ''oidc'' resolved from cached discovery_doc or used as a fallback when the id_token does not contain the desired claims.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 7, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6e92-7989-85fc-2f9dade83d58', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'issuer_url', 'issuer_url', 'OIDC issuer URL. Discovery fetches {issuer}/.well-known/openid-configuration unless discovery_url_override is set. Required when kind = ''oidc''. Used for id_token ''iss'' claim verification.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 8, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6e9d-7afa-a6f4-731d0895de24', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'discovery_url_override', 'discovery_url_override', 'Optional non-standard discovery document URL. When NULL, discovery uses {issuer_url}/.well-known/openid-configuration. Used for IdPs that publish discovery at a non-spec path.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 9, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6ea8-7814-a786-2130f476bfc7', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'discovery_doc', 'discovery_doc', 'Cached OIDC discovery document (authorization_endpoint, token_endpoint, userinfo_endpoint, jwks_uri, issuer, etc.). Refreshed by a background job; auth-server reads endpoints from here at request time when kind = ''oidc''.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"jsonb"}', 10, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6eb2-7f12-8c32-9446ac435651', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'jwks', 'jwks', 'Cached JWKS document used to verify id_token signatures. Refreshed by a background job. NULL until first successful discovery + JWKS fetch.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"jsonb"}', 11, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6ebd-7af8-bbbc-81f3695186be', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'jwks_fetched_at', 'jwks_fetched_at', 'Timestamp of the most recent successful JWKS fetch. Used by the background refresher to age out cache entries and to drive cold-start fetches when NULL.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"timestamptz"}', 12, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6ec7-7f51-82c9-0c2b9f05cc6e', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'client_id', 'client_id', 'OAuth2 / OIDC client_id registered with the IdP. NULL for built-in rows until an admin sets it. Providers with NULL client_id or NULL client_secret_id are treated as not-configured by the sign-in path regardless of the enabled flag.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 13, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6ed2-7dba-a692-1c2630dea8bb', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'client_secret_id', 'client_secret_id', 'Pointer to the row in user_secrets that holds the OAuth2 client_secret (encrypted at rest). NULL only briefly between create_identity_provider and the first rotate_provider_secret. Rotation writes a new user_secrets row and atomically updates this column; the raw secret is never returned to clients.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"uuid"}', 14, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6edd-7381-8fd2-e422ea592234', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'scopes', 'scopes', 'OAuth2 scopes requested in the authorization URL. For kind = ''oidc'' the admin procedure ensures ''openid'' is always present (silently prepended if missing).', NULL, true, false, '{"cast":{"name":"text","array_dimensions":1},"value":[]}', NULL, NULL, NULL, NULL, '{"name":"text","array_dimensions":1}', 15, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6ef2-7d32-a846-24e9474c76dd', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'extra_authorization_params', 'extra_authorization_params', 'Extra query parameters merged into the authorization URL (e.g. {"prompt":"select_account"}). Admin procedure rejects reserved OAuth/OIDC keys: client_id, redirect_uri, state, nonce, code_challenge, code_challenge_method, response_type, scope.', NULL, true, false, '{"cast":{"name":"jsonb"},"value":{}}', NULL, NULL, NULL, NULL, '{"name":"jsonb"}', 16, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6f08-7afa-aa9e-c63929f99710', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'acceptable_client_ids', 'acceptable_client_ids', 'Multi-platform audience allow-list. When non-empty, id_token ''aud'' is validated against client_id OR any value here. Used when one IdP project issues tokens with platform-specific audiences (web vs iOS vs Android).', NULL, true, false, '{"cast":{"name":"text","array_dimensions":1},"value":[]}', NULL, NULL, NULL, NULL, '{"name":"text","array_dimensions":1}', 17, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6f1e-7800-8e2f-3faa79f67989', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'email_optional', 'email_optional', 'When true, sign-in succeeds even if the IdP does not return a verified email. The user is provisioned without an email and can add one later. When false, missing email is a hard error.', NULL, true, false, '{"value":false}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 18, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6f34-79a4-9b15-6dad87f68e4e', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'allow_link_by_email', 'allow_link_by_email', 'When true, an OAuth/OIDC sign-in whose IdP-verified email matches an existing user account auto-links the new identity to that account. When false, an existing-email collision raises IDENTITY_EMAIL_ALREADY_REGISTERED. Only honored when the IdP marks the email as verified.', NULL, true, false, '{"value":false}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 19, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6f4b-7d75-9084-eca98b662926', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'skip_nonce_check', 'skip_nonce_check', 'OIDC only. When true, the auth server does not require / verify the ''nonce'' claim in id_token. ONLY enable for IdPs that demonstrably do not support nonce; weakens replay resistance.', NULL, true, false, '{"value":false}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 20, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-6f62-7d1f-9542-95cd42dd3cb3', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-6e03-77a5-8d95-46056bdd7ccf', 'pkce_enabled', 'pkce_enabled', 'When true, the auth server generates a PKCE code_verifier per authorization request, sends code_challenge with method = S256, and includes code_verifier in the token exchange. PKCE is handled entirely server-side. Default is true; only disable for IdPs that reject PKCE parameters.', NULL, true, false, '{"value":true}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 21, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fa2a1-7052-7efa-a69d-61e115c151c5', '019fa2a1-4faf-7d97-ab36-59264d5d52d8', '019fa2a1-703c-73a4-bcd4-ef0ed194b005', 'id', 'id', 'Unique identifier for each audit event (uuidv7 provides temporal ordering)', NULL, true, false, '{"function":"uuidv7"}', NULL, NULL, NULL, NULL, '{"name":"uuid"}', 0, NULL, NULL, NULL, NULL, NULL, '{}', 'module'),
